  'content.lenormand.26.keyword.0': 'Тайна',
  'content.lenormand.26.keyword.1': 'Знание',
  'content.lenormand.26.keyword.2': 'Учёба',
  'content.lenormand.26.meaning': 'Скрытое знание — тайна, исследование или истина, которую ещё предстоит открыть.',
  'content.lenormand.26.combination.0': 'С Лисой — тайна служит хитрому замыслу.',
  'content.lenormand.26.combination.1': 'С Ключом — тайна раскрывается.',
  'content.lenormand.26.combination.2': 'С Луной — проявляется скрытая интуиция.',
  'content.lenormand.26.timing': 'Раскроется со временем',
