  'content.lenormand.25.keyword.0': 'Обязательство',
  'content.lenormand.25.keyword.1': 'Договор',
  'content.lenormand.25.keyword.2': 'Цикл',
  'content.lenormand.25.meaning': 'Обязательство и обещание — договор, клятва или цикл, связывающий два начала.',
  'content.lenormand.25.combination.0': 'С Сердцем — помолвка или брак.',
  'content.lenormand.25.combination.1': 'С Якорем — устойчивое обязательство.',
  'content.lenormand.25.combination.2': 'С Косой — разрыв связи.',
  'content.lenormand.25.timing': 'Полный цикл, срок обязательства',
