  'content.lenormand.22.keyword.0': 'Выбор',
  'content.lenormand.22.keyword.1': 'Развилка',
  'content.lenormand.22.keyword.2': 'Решение',
  'content.lenormand.22.meaning': 'Развилка на пути — перед вами настоящий выбор, и промедление само становится ответом.',
  'content.lenormand.22.combination.0': 'С Косой — решение принимается быстро.',
  'content.lenormand.22.combination.1': 'С Луной — выбор подсказывает интуиция.',
  'content.lenormand.22.combination.2': 'С Лисой — оба пути служат чьим-то хитрым интересам.',
  'content.lenormand.22.timing': 'Сейчас, время выбирать',
