  'content.lenormand.18.keyword.0': 'Верность',
  'content.lenormand.18.keyword.1': 'Дружба',
  'content.lenormand.18.keyword.2': 'Доверие',
  'content.lenormand.18.meaning': 'Верность и дружба — преданный спутник, который остаётся, когда остальные уходят.',
  'content.lenormand.18.combination.0': 'С Сердцем — преданная любовь.',
  'content.lenormand.18.combination.1': 'С Якорем — прочная дружба.',
  'content.lenormand.18.combination.2': 'С Лисой — лесть со стороны мнимого друга.',
  'content.lenormand.18.timing': 'Устойчиво, в связи с другом',
