  'content.lenormand.16.keyword.0': 'Надежда',
  'content.lenormand.16.keyword.1': 'Ориентир',
  'content.lenormand.16.keyword.2': 'Ясность',
  'content.lenormand.16.meaning': 'Ясное направление и тихая надежда — звёзды снова помогают найти путь.',
  'content.lenormand.16.combination.0': 'С Луной — интуиция и судьба сходятся.',
  'content.lenormand.16.combination.1': 'С Ключом — надежда находит ответ.',
  'content.lenormand.16.combination.2': 'С Тучами — надежда переживает туман сомнений.',
  'content.lenormand.16.timing': 'Следуйте выбранному направлению',
